window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b3e19e54ca80f522"]={"versions": [{"id": "FIG-b3e19e54ca80f522", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm (Ablaufdiagramm) aus der AUTOSAR-Spezifikation der E2E-Bibliothek (AUTOSAR_SWS_E2ELibrary). Es stellt den internen Kontrollfluss zur Berechnung der Zählerdifferenz (<code>Calculate DeltaCounter</code>) dar, wie sie typischerweise im Rahmen von E2E-Prüfprofilen (z. B. E2E-Profil 1) bei der Empfängerprüfung zur Erkennung von Datenverlusten, Wiederholungen oder Sequenzfehlern eingesetzt wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Startknoten (Initial Node)</strong>: Einstiegspunkt der Sequenz.\n</li><li><strong>Aktionsknoten <code>DeltaCounter = ReceivedCounter - State-&gt;LastValidCounter</code></strong>: Subtraktion des zuletzt gültigen Zählerwerts (<code>State-&gt;LastValidCounter</code>) vom aktuell empfangenen Zähler (<code>ReceivedCounter</code>).\n</li><li><strong>Entscheidungsknoten (Decision Node)</strong> mit Bedingung <code>(sint8) DeltaCounter &lt; 0 ?</code>: Vorzeichenbehaftete Prüfung auf Überlauf bzw. negativen Differenzwert.\n</li><li><strong>Aktionsknoten <code>DeltaCounter = DeltaCounter + 16</code></strong>: Modulo-Korrektur des Zählerüberlaufs für 4-Bit-Zähler (Wertebereich 0 bis 15).\n</li><li><strong>Zusammenführungsknoten (Merge Node)</strong>: Zusammenführung des korrigierten Pfads (<code>[TRUE]</code>) und des direkten Pfads (<code>[FALSE]</code>).\n</li><li><strong>Aktivitätsendknoten (Activity Final Node)</strong>: Abschluss der Berechnung mit dem finalen Wert von <code>DeltaCounter</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Aktivität beginnt am Startknoten.\n</li><li>Im ersten Aktionsschritt wird <code>DeltaCounter</code> als Differenz aus <code>ReceivedCounter</code> und dem Zustandswert <code>State-&gt;LastValidCounter</code> ermittelt.\n</li><li>Am Verzweigungsknoten wird die Bedingung <code>(sint8) DeltaCounter &lt; 0 ?</code> ausgewertet:\n<ul class=\"fig-list\"><li>Pfad <code>[TRUE]</code>: Wenn die vorzeichenbehaftete Differenz negativ ist (Zählerüberlauf aufgetreten), wird <code>DeltaCounter</code> um <code>16</code> erhöht.\n</li><li>Pfad <code>[FALSE]</code>: Wenn die Differenz größer oder gleich null ist, wird die Verzweigung unverändert passiert.\n</li></ul>\n</li><li>Beide Pfade werden im Merge-Knoten zusammengeführt und die Aktivität endet am Endknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlicher Berechnungsalgorithmus für die Differenzermittlung eines 4-Bit-Zählers (Modulobereich 16) in der E2E-Bibliothek. Die explizite Typkonvertierung nach <code>(sint8)</code> stellt sicher, dass das Ergebnis der Differenz vorzeichenbehaftet interpretiert wird, um einen Zählerüberlauf (Wrap-Around) korrekt über die Addition von 16 zu kompensieren. Entwickler müssen sicherstellen, dass die verwendeten Zählervariablen und Datentypen im Implementierungscode dem spezifizierten Wertebereich und Vorzeichenverhalten entsprechen.</p>"}, {"id": "FIG-f867ad6f135a0311", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm (Ablaufdiagramm) aus der AUTOSAR-Spezifikation der E2E-Bibliothek (AUTOSAR_SWS_E2ELibrary). Es stellt den internen Kontrollfluss zur Berechnung der Zählerdifferenz (<code>Calculate DeltaCounter</code>) dar, wie sie typischerweise im Rahmen von E2E-Prüfprofilen (z. B. E2E-Profil 1) bei der Empfängerprüfung zur Erkennung von Datenverlusten, Wiederholungen oder Sequenzfehlern eingesetzt wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Startknoten (Initial Node)</strong>: Einstiegspunkt der Sequenz.\n</li><li><strong>Aktionsknoten <code>DeltaCounter = ReceivedCounter - State-&gt;LastValidCounter</code></strong>: Subtraktion des zuletzt gültigen Zählerwerts (<code>State-&gt;LastValidCounter</code>) vom aktuell empfangenen Zähler (<code>ReceivedCounter</code>).\n</li><li><strong>Entscheidungsknoten (Decision Node)</strong> mit Bedingung <code>(sint8) DeltaCounter &lt; 0 ?</code>: Vorzeichenbehaftete Prüfung auf Überlauf bzw. negativen Differenzwert.\n</li><li><strong>Aktionsknoten <code>DeltaCounter = DeltaCounter + 16</code></strong>: Modulo-Korrektur des Zählerüberlaufs für 4-Bit-Zähler (Wertebereich 0 bis 15).\n</li><li><strong>Zusammenführungsknoten (Merge Node)</strong>: Zusammenführung des korrigierten Pfads (<code>[TRUE]</code>) und des direkten Pfads (<code>[FALSE]</code>).\n</li><li><strong>Aktivitätsendknoten (Activity Final Node)</strong>: Abschluss der Berechnung mit dem finalen Wert von <code>DeltaCounter</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Aktivität beginnt am Startknoten.\n</li><li>Im ersten Aktionsschritt wird <code>DeltaCounter</code> als Differenz aus <code>ReceivedCounter</code> und dem Zustandswert <code>State-&gt;LastValidCounter</code> ermittelt.\n</li><li>Am Verzweigungsknoten wird die Bedingung <code>(sint8) DeltaCounter &lt; 0 ?</code> ausgewertet:\n<ul class=\"fig-list\"><li>Pfad <code>[TRUE]</code>: Wenn die vorzeichenbehaftete Differenz negativ ist (Zählerüberlauf aufgetreten), wird <code>DeltaCounter</code> um <code>16</code> erhöht.\n</li><li>Pfad <code>[FALSE]</code>: Wenn die Differenz größer oder gleich null ist, wird die Verzweigung unverändert passiert.\n</li></ul>\n</li><li>Beide Pfade werden im Merge-Knoten zusammengeführt und die Aktivität endet am Endknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlicher Berechnungsalgorithmus für die Differenzermittlung eines 4-Bit-Zählers (Modulobereich 16) in der E2E-Bibliothek. Die explizite Typkonvertierung nach <code>(sint8)</code> stellt sicher, dass das Ergebnis der Differenz vorzeichenbehaftet interpretiert wird, um einen Zählerüberlauf (Wrap-Around) korrekt über die Addition von 16 zu kompensieren. Entwickler müssen sicherstellen, dass die verwendeten Zählervariablen und Datentypen im Implementierungscode dem spezifizierten Wertebereich und Vorzeichenverhalten entsprechen.</p>"}, {"id": "FIG-7e1a3c6542d5b9fb", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm (Ablaufdiagramm) aus der AUTOSAR-Spezifikation der E2E-Bibliothek (AUTOSAR_SWS_E2ELibrary). Es stellt den internen Kontrollfluss zur Berechnung der Zählerdifferenz (<code>Calculate DeltaCounter</code>) dar, wie sie typischerweise im Rahmen von E2E-Prüfprofilen (z. B. E2E-Profil 1) bei der Empfängerprüfung zur Erkennung von Datenverlusten, Wiederholungen oder Sequenzfehlern eingesetzt wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Startknoten (Initial Node)</strong>: Einstiegspunkt der Sequenz.\n</li><li><strong>Aktionsknoten <code>DeltaCounter = ReceivedCounter - State-&gt;LastValidCounter</code></strong>: Subtraktion des zuletzt gültigen Zählerwerts (<code>State-&gt;LastValidCounter</code>) vom aktuell empfangenen Zähler (<code>ReceivedCounter</code>).\n</li><li><strong>Entscheidungsknoten (Decision Node)</strong> mit Bedingung <code>(sint8) DeltaCounter &lt; 0 ?</code>: Vorzeichenbehaftete Prüfung auf Überlauf bzw. negativen Differenzwert.\n</li><li><strong>Aktionsknoten <code>DeltaCounter = DeltaCounter + 16</code></strong>: Modulo-Korrektur des Zählerüberlaufs für 4-Bit-Zähler (Wertebereich 0 bis 15).\n</li><li><strong>Zusammenführungsknoten (Merge Node)</strong>: Zusammenführung des korrigierten Pfads (<code>[TRUE]</code>) und des direkten Pfads (<code>[FALSE]</code>).\n</li><li><strong>Aktivitätsendknoten (Activity Final Node)</strong>: Abschluss der Berechnung mit dem finalen Wert von <code>DeltaCounter</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Aktivität beginnt am Startknoten.\n</li><li>Im ersten Aktionsschritt wird <code>DeltaCounter</code> als Differenz aus <code>ReceivedCounter</code> und dem Zustandswert <code>State-&gt;LastValidCounter</code> ermittelt.\n</li><li>Am Verzweigungsknoten wird die Bedingung <code>(sint8) DeltaCounter &lt; 0 ?</code> ausgewertet:\n<ul class=\"fig-list\"><li>Pfad <code>[TRUE]</code>: Wenn die vorzeichenbehaftete Differenz negativ ist (Zählerüberlauf aufgetreten), wird <code>DeltaCounter</code> um <code>16</code> erhöht.\n</li><li>Pfad <code>[FALSE]</code>: Wenn die Differenz größer oder gleich null ist, wird die Verzweigung unverändert passiert.\n</li></ul>\n</li><li>Beide Pfade werden im Merge-Knoten zusammengeführt und die Aktivität endet am Endknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlicher Berechnungsalgorithmus für die Differenzermittlung eines 4-Bit-Zählers (Modulobereich 16) in der E2E-Bibliothek. Die explizite Typkonvertierung nach <code>(sint8)</code> stellt sicher, dass das Ergebnis der Differenz vorzeichenbehaftet interpretiert wird, um einen Zählerüberlauf (Wrap-Around) korrekt über die Addition von 16 zu kompensieren. Entwickler müssen sicherstellen, dass die verwendeten Zählervariablen und Datentypen im Implementierungscode dem spezifizierten Wertebereich und Vorzeichenverhalten entsprechen.</p>"}], "trans": [{"from": "FIG-b3e19e54ca80f522", "to": "FIG-f867ad6f135a0311", "fr": "R4.0.3", "tr": "R4.2.2", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Diagrammkopf: Das am oberen Bildrand abgeschnittene Textfragment („DeltaCounter“) oberhalb des Startknotens wurde entfernt.\n</li></ul>"}, {"from": "FIG-f867ad6f135a0311", "to": "FIG-7e1a3c6542d5b9fb", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
